import * as THREE from 'three/webgpu';
import { MeshBasicMaterial } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(
  config: NodeConfig,
  ctx: NodeContext
): THREE.Object3D {
  const group = new THREE.Group();

  // Create plane geometry with aspect ratio matching 512x320 image (1.6:1)
  const planeGeo = new THREE.PlaneGeometry(1, 0.625);

  // Load texture via cached loader
  const cardTexture = ctx.textureLoader.load(
    config.assets?.imageUrl || '/prism-mock/home/nodes/feature-card.png'
  );

  // Create material (no lighting effects needed)
  const planeMat = new MeshBasicMaterial({
    map: cardTexture,
    transparent: true,
    side: THREE.DoubleSide,
  });

  // Create plane mesh
  const planeMesh = new THREE.Mesh(planeGeo, planeMat);
  group.add(planeMesh);

  // Render text content if provided
  if (config.textContent && config.textContent.length > 0) {
    const textItem = config.textContent[0];
    const textStr = textItem.text || 'Collection 3';

    const textObject = ctx.fontAtlas.createText(textStr, {
      fontSize: 0.34,
      color: 0x16161d,
      weight: 400,
      font: 'Lora',
    });

    if (textObject) {
      textObject.position.z = 0.02;
      group.add(textObject);
    }
  }

  // Apply scene position, rotation, and scale
  if (config.scenePosition) {
    const { x, y, z, rotationXYZ, scaleXYZ } = config.scenePosition;
    group.position.set(x, y, z);
    if (rotationXYZ) {
      group.rotation.set(rotationXYZ[0], rotationXYZ[1], rotationXYZ[2]);
    }
    if (scaleXYZ) {
      group.scale.set(scaleXYZ[0], scaleXYZ[1], scaleXYZ[2]);
    }
  }

  // Setup cleanup function
  group.userData.cleanup = () => {
    planeGeo.dispose();
    planeMat.dispose();
    cardTexture.dispose();
    gsap.killTweensOf(group);
    gsap.killTweensOf(planeMesh);
  };

  // Setup event handlers
  group.userData.handlers = {
    onPointerOver: undefined,
    onPointerOut: undefined,
    onClick: undefined,
  };

  return group;
}
